css:
.fx-mag{display:grid;justify-items:center;text-align:center;gap:1em}
.fx-mag h2{font-size:2.3em}.fx-mag p{opacity:.6}
.fx-mag .zone{padding:3.2em 5em;margin-top:.6em}
.fx-mag .b{display:inline-flex;padding:1.1em 2.2em;border-radius:999px;background:var(--primary);color:var(--on-primary);font:700 1em var(--font-body);border:0;cursor:pointer;transition:transform calc(.35s/var(--speed)) cubic-bezier(.2,.8,.2,1),background .3s}
.fx-mag .b span{display:inline-block;transition:transform calc(.35s/var(--speed)) cubic-bezier(.2,.8,.2,1)}
.fx-mag .b:hover{background:var(--accent);color:var(--on-accent)}
/* touch: :hover mirrored as .is-tap */
.fx-mag .b.is-tap{background:var(--accent);color:var(--on-accent)}

js:
/* touch: nudge toward the finger on press */
if(matchMedia('(pointer:coarse)').matches&&!matchMedia('(prefers-reduced-motion:reduce)').matches){
document.querySelectorAll('.fx-mag .zone').forEach(function(z){var b=z.querySelector('.b'),s=b.querySelector('span');
z.addEventListener('pointerdown',function(e){var r=b.getBoundingClientRect(),x=e.clientX-(r.left+r.width/2),y=e.clientY-(r.top+r.height/2);
b.style.transform='translate('+x*.3+'px,'+y*.4+'px) scale(.96)';s.style.transform='translate('+x*.1+'px,'+y*.14+'px)'});
function up(){b.style.transform='';s.style.transform=''}z.addEventListener('pointerup',up);z.addEventListener('pointercancel',up)})}
(function(){if(!matchMedia('(hover:hover) and (pointer:fine)').matches||matchMedia('(prefers-reduced-motion:reduce)').matches)return;
document.querySelectorAll('.fx-mag .zone').forEach(function(z){var b=z.querySelector('.b'),s=b.querySelector('span');
z.addEventListener('mousemove',function(e){var r=b.getBoundingClientRect(),x=e.clientX-(r.left+r.width/2),y=e.clientY-(r.top+r.height/2);
b.style.transform='translate('+x*.32+'px,'+y*.4+'px)';s.style.transform='translate('+x*.12+'px,'+y*.16+'px)'});
z.addEventListener('mouseleave',function(){b.style.transform='';s.style.transform=''})})})();
/* fx-touch */
(function(){if(window.__fxTap)return;window.__fxTap=1;var cur=[];function clr(){cur.forEach(function(e){e.classList.remove('is-tap')});cur=[]}
document.addEventListener('pointerdown',function(e){if(e.pointerType!=='touch')return;clr();var n=e.target.closest&&e.target.closest('.fx');if(!n)return;for(var el=e.target;el&&el!==n.parentNode;el=el.parentNode){if(el.classList){el.classList.add('is-tap');cur.push(el)}}},{passive:true});
document.addEventListener('pointerup',function(){setTimeout(clr,1400)},{passive:true})})();
